begin;
set local search_path=public,extensions;
select no_plan();
select ok(to_regprocedure('public.get_merchant_naver_cafe(uuid)') is not null,'Naver owner boundary is installed');
insert into auth.users(id,email,raw_app_meta_data) values
('13000000-0000-4000-8000-000000000001','naver-owner@example.invalid','{"merchant_enabled":true}'),
('13000000-0000-4000-8000-000000000002','naver-other@example.invalid','{"merchant_enabled":true}'),
('13000000-0000-4000-8000-000000000003','naver-admin@example.invalid','{"role":"admin","merchant_enabled":true}');
insert into public.profiles(id,nickname,city_id,terms_accepted_at,privacy_accepted_at,ai_safety_consent_at,consent_version) values
('13000000-0000-4000-8000-000000000001','카페소유검사','vancouver',now(),now(),now(),'test'),
('13000000-0000-4000-8000-000000000002','카페다른검사','vancouver',now(),now(),now(),'test'),
('13000000-0000-4000-8000-000000000003','카페관리검사','vancouver',now(),now(),now(),'test');
insert into private.merchants(id,name,city_id,owner_id,owner_verified_at,status,consent,consent_note) values
('13010000-0000-4000-8000-000000000001','실제 업체 아닌 카페 검사','vancouver','13000000-0000-4000-8000-000000000001',now(),'trial','granted','모의 검사 동의');
select set_config('request.jwt.claims','{"sub":"13000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is(public.get_merchant_naver_cafe('13010000-0000-4000-8000-000000000001')->'connection','null'::jsonb,'no fabricated connected account');
select lives_ok($$select public.begin_merchant_naver_oauth('13010000-0000-4000-8000-000000000001',repeat('a',64))$$,'verified enabled owner may start OAuth');
select throws_ok($$select public.consume_merchant_naver_oauth(repeat('a',64),'13000000-0000-4000-8000-000000000001')$$,'42501',null,'client cannot consume a provider callback directly');
select throws_ok($$select * from private.merchant_naver_states$$,'42501',null,'client cannot read stored states');
reset role;
set local role service_role;
select throws_ok($$select public.consume_merchant_naver_oauth(repeat('a',64),'13000000-0000-4000-8000-000000000002')$$,'P0001','INVALID_NAVER_STATE','state is bound to actual authenticated browser user');
select is(public.consume_merchant_naver_oauth(repeat('a',64),'13000000-0000-4000-8000-000000000001')->>'merchant_id','13010000-0000-4000-8000-000000000001','state restores its actual business');
select throws_ok($$select public.consume_merchant_naver_oauth(repeat('a',64),'13000000-0000-4000-8000-000000000001')$$,'P0001','INVALID_NAVER_STATE','state cannot be used twice');
select lives_ok($$select public.complete_merchant_naver_oauth(repeat('a',64),repeat('ciphertext',10),now()+interval '1 hour')$$,'service stores only encrypted provider credentials');
select throws_ok($$select public.complete_merchant_naver_oauth(repeat('a',64),repeat('ciphertext',10),now()+interval '1 hour')$$,'P0001','INVALID_NAVER_STATE','OAuth completion cannot overwrite a newer connection');
reset role;
set local role authenticated;
select ok(public.get_merchant_naver_cafe('13010000-0000-4000-8000-000000000001')->'connection' is distinct from 'null'::jsonb,'owner sees connected status');
select ok(position('ciphertext' in public.get_merchant_naver_cafe('13010000-0000-4000-8000-000000000001')::text)=0,'status never contains provider token');
select throws_ok($$select public.get_merchant_naver_tokens('13010000-0000-4000-8000-000000000001','13000000-0000-4000-8000-000000000001')$$,'42501',null,'user cannot read encrypted or plaintext provider token');
reset role;
select set_config('request.jwt.claims','{"sub":"13000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.get_merchant_naver_cafe('13010000-0000-4000-8000-000000000001')$$,'P0001','MERCHANT_ACCESS_REQUIRED','other enabled business account cannot access this connection');
reset role;
select set_config('request.jwt.claims','{"sub":"13000000-0000-4000-8000-000000000003","role":"authenticated","app_metadata":{"role":"admin"},"aal":"aal2"}',true);
set local role authenticated;
select throws_ok($$select public.begin_merchant_naver_oauth('13010000-0000-4000-8000-000000000001',repeat('b',64))$$,'P0001','MERCHANT_ACCESS_REQUIRED','admin role does not bypass actual cafe owner');
reset role;
update private.merchants set owner_verified_at=null where id='13010000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"sub":"13000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.begin_merchant_naver_oauth('13010000-0000-4000-8000-000000000001',repeat('c',64))$$,'P0001','MERCHANT_OWNER_VERIFICATION_REQUIRED','unverified ownership cannot connect');
reset role;
update private.merchants set owner_verified_at=now() where id='13010000-0000-4000-8000-000000000001';
insert into private.merchant_workspace_drafts(id,merchant_id,channel,title,body,tag_slug,kind,approved_at,approved_by,image_paths) values
('13020000-0000-4000-8000-000000000001','13010000-0000-4000-8000-000000000001','casmo','모의 저장 제목','실제 고객에게 게시하지 않는 모의 원고','life','story',now(),'13000000-0000-4000-8000-000000000001','{}');
set local role authenticated;
select throws_ok($$select public.reserve_merchant_naver_publish('13010000-0000-4000-8000-000000000001','13020000-0000-4000-8000-000000000001',now()-interval '1 second','13030000-0000-4000-8000-000000000001','123','4','{}')$$,'P0001','MERCHANT_DRAFT_CHANGED','older reviewed revision cannot dispatch');
select is(public.reserve_merchant_naver_publish('13010000-0000-4000-8000-000000000001','13020000-0000-4000-8000-000000000001',now(),'13030000-0000-4000-8000-000000000001','123','4','{}')->>'status','prepared','owner reserves exact approved stored revision');
select is(public.reserve_merchant_naver_publish('13010000-0000-4000-8000-000000000001','13020000-0000-4000-8000-000000000001',now(),'13030000-0000-4000-8000-000000000002','123','4','{}')->>'id','13030000-0000-4000-8000-000000000001','another request ID cannot duplicate the same draft revision');
select throws_ok($$select public.reserve_merchant_naver_publish('13010000-0000-4000-8000-000000000001','13020000-0000-4000-8000-000000000001',now(),'13030000-0000-4000-8000-000000000001','123','5','{}')$$,'P0001','MERCHANT_REQUEST_CONFLICT','same request cannot switch the reviewed board');
select lives_ok($$select public.begin_merchant_naver_oauth('13010000-0000-4000-8000-000000000001',repeat('e',64))$$,'OAuth state created before revocation');
reset role;
update auth.users set raw_app_meta_data='{"merchant_enabled":false}' where id='13000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"sub":"13000000-0000-4000-8000-000000000001","role":"authenticated","app_metadata":{"merchant_enabled":true}}',true);
set local role authenticated;
select throws_ok($$select public.claim_merchant_naver_publish('13030000-0000-4000-8000-000000000001')$$,'P0001','MERCHANT_ACCESS_REQUIRED','NO revokes before dispatch even with stale JWT');
reset role;
set local role service_role;
select throws_ok($$select public.get_merchant_naver_tokens('13010000-0000-4000-8000-000000000001','13000000-0000-4000-8000-000000000001')$$,'P0001','MERCHANT_ACCESS_REQUIRED','service token read also enforces current capability');
select throws_ok($$select public.consume_merchant_naver_oauth(repeat('e',64),'13000000-0000-4000-8000-000000000001')$$,'P0001','MERCHANT_ACCESS_REQUIRED','OAuth callback cannot finish after NO');
reset role;
update auth.users set raw_app_meta_data='{"merchant_enabled":true}' where id='13000000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.claim_merchant_naver_publish('13030000-0000-4000-8000-000000000001')->>'should_send','true','one caller claims the provider dispatch');
select is(public.claim_merchant_naver_publish('13030000-0000-4000-8000-000000000001')->>'should_send','false','in-flight claim cannot dispatch twice');
select throws_ok($$select public.save_merchant_workspace_draft('13010000-0000-4000-8000-000000000001','13020000-0000-4000-8000-000000000001','casmo','수정시도','검토 후 원고 수정',null,'life','story')$$,'P0001','NAVER_PUBLISH_UNCERTAIN','in-flight draft is frozen');
reset role;
set local role service_role;
select throws_ok($$select public.complete_merchant_naver_publish('13030000-0000-4000-8000-000000000001','succeeded','https://evil.ca/17',null)$$,'P0001','INVALID_NAVER_RESULT','service receipt cannot introduce an arbitrary URL');
select is(public.complete_merchant_naver_publish('13030000-0000-4000-8000-000000000001','succeeded','https://cafe.naver.com/testcafe/17',null)->>'status','succeeded','simulated actual provider receipt completes request');
reset role;
select is((select external_url from private.merchant_workspace_drafts where id='13020000-0000-4000-8000-000000000001'),'https://cafe.naver.com/testcafe/17','receipt updates the exact approved draft link');
select is((select snapshot->>'body' from private.merchant_naver_requests where id='13030000-0000-4000-8000-000000000001'),'실제 고객에게 게시하지 않는 모의 원고','original reviewed content retained in request audit');
set local role authenticated;
select is(public.claim_merchant_naver_publish('13030000-0000-4000-8000-000000000001')->>'should_send','false','successful receipt never dispatches again');
select lives_ok($$select public.begin_merchant_naver_oauth('13010000-0000-4000-8000-000000000001',repeat('d',64))$$,'second OAuth request prepared');
reset role;
update private.merchant_naver_states set expires_at=now()-interval '1 minute' where state_hash=repeat('d',64);
set local role service_role;
select throws_ok($$select public.consume_merchant_naver_oauth(repeat('d',64),'13000000-0000-4000-8000-000000000001')$$,'P0001','INVALID_NAVER_STATE','expired state cannot authorize');
reset role;
insert into private.merchant_workspace_drafts(id,merchant_id,channel,title,body,tag_slug,kind,image_paths) values
('13020000-0000-4000-8000-000000000002','13010000-0000-4000-8000-000000000001','casmo','불확실 결과 검사','승인 후 유지할 모의 원고','life','story','{}');
set local role authenticated;
select throws_ok($$select public.reserve_merchant_naver_publish('13010000-0000-4000-8000-000000000001','13020000-0000-4000-8000-000000000002',now(),'13030000-0000-4000-8000-000000000002','123','4','{}')$$,'P0001','MERCHANT_DRAFT_APPROVAL_REQUIRED','unapproved saved text cannot post externally');
reset role;
insert into private.watch_terms(term,category,severity,active) values('카페감시검사어','fraud','high',true) on conflict do nothing;
update private.merchant_workspace_drafts set approved_at=now(),approved_by='13000000-0000-4000-8000-000000000001',body='카페감시검사어 포함' where id='13020000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.reserve_merchant_naver_publish('13010000-0000-4000-8000-000000000001','13020000-0000-4000-8000-000000000002',now(),'13030000-0000-4000-8000-000000000002','123','4','{}')$$,'P0001','NAVER_CONTENT_REVIEW_REQUIRED','active safety watch terms fail closed before external request');
reset role;
update private.merchant_workspace_drafts set body='승인 후 유지할 모의 원고',image_paths=array['13000000-0000-4000-8000-000000000002/not-mine.webp'] where id='13020000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.reserve_merchant_naver_publish('13010000-0000-4000-8000-000000000001','13020000-0000-4000-8000-000000000002',now(),'13030000-0000-4000-8000-000000000002','123','4',array['13000000-0000-4000-8000-000000000002/not-mine.webp'])$$,'P0001','INVALID_IMAGE_PATH','foreign owner photos cannot leave through provider');
reset role;
update private.merchant_workspace_drafts set image_paths=array['13000000-0000-4000-8000-000000000001/missing.webp'] where id='13020000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.reserve_merchant_naver_publish('13010000-0000-4000-8000-000000000001','13020000-0000-4000-8000-000000000002',now(),'13030000-0000-4000-8000-000000000002','123','4',array['13000000-0000-4000-8000-000000000001/missing.webp'])$$,'P0001','NAVER_INVALID_PHOTO','missing storage object is rejected before provider request');
reset role;
update private.merchant_workspace_drafts set image_paths='{}' where id='13020000-0000-4000-8000-000000000002';
set local role authenticated;
select lives_ok($$select public.reserve_merchant_naver_publish('13010000-0000-4000-8000-000000000001','13020000-0000-4000-8000-000000000002',now(),'13030000-0000-4000-8000-000000000002','123','4','{}')$$,'second mock request reserved');
reset role;
update private.merchant_workspace_drafts set body='예약 뒤 바뀐 원고' where id='13020000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.claim_merchant_naver_publish('13030000-0000-4000-8000-000000000002')$$,'P0001','MERCHANT_DRAFT_CHANGED','snapshot comparison also detects changes at equal transaction timestamps');
reset role;
update private.merchant_workspace_drafts set body='승인 후 유지할 모의 원고' where id='13020000-0000-4000-8000-000000000002';
set local role authenticated;
select is(public.claim_merchant_naver_publish('13030000-0000-4000-8000-000000000002')->>'should_send','true','valid second mock request claimed once');
reset role;
set local role service_role;
select is(public.complete_merchant_naver_publish('13030000-0000-4000-8000-000000000002','uncertain',null,'NAVER_PUBLISH_UNCERTAIN')->>'status','uncertain','provider timeout persists an uncertain request');
reset role;
set local role authenticated;
select is(public.claim_merchant_naver_publish('13030000-0000-4000-8000-000000000002')->>'should_send','false','uncertain result never dispatches again');
select throws_ok($$select public.save_merchant_workspace_draft('13010000-0000-4000-8000-000000000001','13020000-0000-4000-8000-000000000002','casmo','재전송 편집','같은 원고를 바꾸어 재전송',null,'life','story')$$,'P0001','NAVER_PUBLISH_UNCERTAIN','uncertain draft remains frozen to prevent accidental repost');
select ok(to_regprocedure('public.cancel_merchant_naver_preparation(uuid,uuid)') is not null,'unused preparation has an atomic cancellation boundary');
select is(public.cancel_merchant_naver_preparation('13010000-0000-4000-8000-000000000001','13030000-0000-4000-8000-000000000002')->>'status','uncertain','cancellation cannot release or resend an uncertain request');
reset role;
insert into private.merchant_workspace_drafts(id,merchant_id,channel,title,body,tag_slug,kind,approved_at,approved_by,image_paths) values
('13020000-0000-4000-8000-000000000003','13010000-0000-4000-8000-000000000001','casmo','취소할 준비 원고','발행 시작 전 취소할 테스트 원고','life','story',now(),'13000000-0000-4000-8000-000000000001','{}');
set local role authenticated;
select lives_ok($$select public.reserve_merchant_naver_publish('13010000-0000-4000-8000-000000000001','13020000-0000-4000-8000-000000000003',now(),'13030000-0000-4000-8000-000000000003','123','4','{}')$$,'unused third request prepared');
select is(public.cancel_merchant_naver_preparation('13010000-0000-4000-8000-000000000001','13030000-0000-4000-8000-000000000003')->>'error_code','NAVER_PREPARATION_CANCELLED','preparation cancellation is saved under request lock');
select is(public.claim_merchant_naver_publish('13030000-0000-4000-8000-000000000003')->>'should_send','false','late dispatch worker cannot claim cancelled preparation');
select lives_ok($$select public.save_merchant_workspace_draft('13010000-0000-4000-8000-000000000001','13020000-0000-4000-8000-000000000003','casmo','취소 뒤 수정','안전하게 원고를 수정합니다',null,'life','story')$$,'cancelled preparation allows draft editing');
reset role;
update public.profiles set account_status='deleted' where id='13000000-0000-4000-8000-000000000001';
select is((select count(*) from private.merchant_naver_connections where user_id='13000000-0000-4000-8000-000000000001'),0::bigint,'account erasure removes connection token');
select is((select count(*) from private.merchant_naver_requests where user_id='13000000-0000-4000-8000-000000000001'),0::bigint,'account erasure removes reviewed content snapshots');
select ok(not has_function_privilege('anon','public.consume_merchant_naver_oauth(text,uuid)','execute'),'anonymous caller cannot consume OAuth state');
select ok(not has_function_privilege('authenticated','public.complete_merchant_naver_publish(uuid,text,text,text)','execute'),'owner cannot fake a verified provider receipt');
select * from finish();
rollback;
